using System.IO.Abstractions;

namespace MyApp.Services;

/// <summary>
/// Thin wrapper around <see cref="IFileSystem"/> that provides commonly used
/// file-system operations in a testable, mockable manner.
/// Register as a singleton in DI alongside <see cref="FileSystem"/>.
/// </summary>
public interface IFileSystemWrapper
{
    bool FileExists(string path);
    string ReadAllText(string path);
    void WriteAllText(string path, string contents);
    byte[] ReadAllBytes(string path);
    void WriteAllBytes(string path, byte[] bytes);
    string[] ReadAllLines(string path);
    void DeleteFile(string path);

    bool DirectoryExists(string path);
    void CreateDirectory(string path);
    void DeleteDirectory(string path, bool recursive);
    string[] GetFiles(string path, string searchPattern, SearchOption searchOption);
    string[] GetDirectories(string path);

    Stream OpenRead(string path);
    Stream Create(string path);

    string GetFullPath(string path);
    string Combine(params string[] paths);
}

public class FileSystemWrapper : IFileSystemWrapper
{
    private readonly IFileSystem _fileSystem;

    public FileSystemWrapper(IFileSystem fileSystem)
    {
        _fileSystem = fileSystem;
    }

    public bool FileExists(string path) =>
        _fileSystem.File.Exists(path);

    public string ReadAllText(string path) =>
        _fileSystem.File.ReadAllText(path);

    public void WriteAllText(string path, string contents) =>
        _fileSystem.File.WriteAllText(path, contents);

    public byte[] ReadAllBytes(string path) =>
        _fileSystem.File.ReadAllBytes(path);

    public void WriteAllBytes(string path, byte[] bytes) =>
        _fileSystem.File.WriteAllBytes(path, bytes);

    public string[] ReadAllLines(string path) =>
        _fileSystem.File.ReadAllLines(path);

    public void DeleteFile(string path) =>
        _fileSystem.File.Delete(path);

    public bool DirectoryExists(string path) =>
        _fileSystem.Directory.Exists(path);

    public void CreateDirectory(string path) =>
        _fileSystem.Directory.CreateDirectory(path);

    public void DeleteDirectory(string path, bool recursive) =>
        _fileSystem.Directory.Delete(path, recursive);

    public string[] GetFiles(string path, string searchPattern, SearchOption searchOption) =>
        _fileSystem.Directory.GetFiles(path, searchPattern, searchOption);

    public string[] GetDirectories(string path) =>
        _fileSystem.Directory.GetDirectories(path);

    public Stream OpenRead(string path) =>
        _fileSystem.File.OpenRead(path);

    public Stream Create(string path) =>
        _fileSystem.File.Create(path);

    public string GetFullPath(string path) =>
        _fileSystem.Path.GetFullPath(path);

    public string Combine(params string[] paths) =>
        _fileSystem.Path.Combine(paths);
}

